def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    pts={v:(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v}
    paths={}
    moves={1:(-1,2),2:(0,-4),3:(3,0),6:(-6,0)}
    for v,(r,c) in pts.items():
        dr,dc=moves[v]; rr,cc=r+dr,c+dc
        path=[]
        if v==1:
            for x in range(c+1,c+3):
                if 0<=x<w: out[r][x]=5; path.append((r,x))
            if 0<=rr<h and 0<=cc<w: out[rr][cc]=1
            if 0<=cc<w: path.append((rr,cc))
        else:
            step_r=(dr>0)-(dr<0); step_c=(dc>0)-(dc<0)
            y,x=r+step_r,c+step_c
            while (y,x)!=(rr,cc) and 0<=y<h and 0<=x<w:
                out[y][x]=5; path.append((y,x)); y+=step_r; x+=step_c
            if 0<=rr<h and 0<=cc<w:
                out[rr][cc]=v; path.append((rr,cc))
        paths[v]=set(path)
    # Where paths from different markers cross, make a 4 and extend down-left.
    allpaths=list(paths.values())
    crosses=set()
    for i in range(len(allpaths)):
        for j in range(i+1,len(allpaths)):
            crosses |= allpaths[i] & allpaths[j]
    for r,c in crosses:
        out[r][c]=4
        r+=1; c-=1
        while 0<=r<h and 0<=c<w:
            out[r][c]=4; r+=1;c-=1
    return out
